Each input string encodes one tree node. Its depth is the number of leading tab characters, and the remainder is its name. A valid outline is non-empty, has exactly one depth-zero root, has no empty names, and may increase depth by at most one between consecutive lines. A line at depth `d > 0` becomes a child of the most recent node at depth `d-1`; children retain input order. For malformed input, return a nil root and a non-nil error without panicking. For valid input, return the tree and a nil error. The function must not modify `lines`.

```go
package solution

import (
	"errors"
	"fmt"
)

type Node struct {
	Name     string
	Children []*Node
}

func ParseOutline(lines []string) (*Node, error) {
	if len(lines) == 0 {
		return nil, errors.New("outline is empty")
	}

	var root *Node
	stack := make([]*Node, 0)
	for index, line := range lines {
		depth := 0
		for depth < len(line) && line[depth] == '\t' {
			depth++
		}
		name := line[depth:]
		if name == "" {
			return nil, fmt.Errorf("line %d has an empty name", index)
		}

		node := &Node{Name: name}
		if depth == 0 {
			if root != nil {
				return nil, fmt.Errorf("line %d starts another root", index)
			}
			root = node
		} else {
			parent := stack[depth-1]
			parent.Children = append(parent.Children, node)
		}

		stack = stack[:depth]
		stack = append(stack, node)
	}
	return root, nil
}
```

